                        if 0<=x<H and 0<=y<W and I[x][y]==v and (x,y) not in cs:
                            cs.add((x,y)); st.append((x,y))
                seen|=cs
                ys=[x for x,_ in cs]; xs=[y for _,y in cs]
                objs.append({'v':v,'rows':min(ys),max(ys),'cols':min(xs),max(xs),'cells':sorted(cs)})
    # anchor col = min col of color-2 object (if any) else W//2
    anc=min(c for o in objs if o['v']==2 and o['rows']==min([r for o2 in objs if o2['v']==2])) if any(o['v']==2 for o in objs) else W//2
    print('anchor',anc,[(o['v'],o['rows'],o['cols']) for o in objs])
    kept=[o for o in objs if o['v']!=2]
    # drop: if two objects of same color, keep... demo3 dropped bottom 1; assume keep first (topmost/leftmost)
    uniq={}
    for o in kept:
        if o['v'] not in uniq or (o['rows'],o['cols']) < uniq[o['v']]:
            uniq[o['v']]=o
    kept=list(uniq.values())
    kept.sort(key=lambda o:-o['v'])
    out=[[0]*W for _ in range(9)]
    top=0
    for o in kept:
        h=o['maxrows']-o['rows']+1; w=o['maxcols']-o['cols']+1
        for i,(r,c) in enumerate(sorted(o['cells'])):
            rr=top+r-o['rows']; cc=anc+c-o['cols']
            if 0<=rr<9 and 0<=cc<15: out[rr][cc]=o['v']
        top+=h
    return out
