# verify rule hypothesis on all demos: kept pieces (non-2, above separator), stack below slot-anchored piece
def solve(I):
    H,W=len(I),len(I[0])
    sep=[r for r in range(H) if all(I[r][c]==5 for c in range(W))][0]
    objs=[]
    for r in range(H):
        for c in range(W):
            v=I[r][c]
            if v!=5 and r<sep and (r,c) not in {(x,y) for x in range(H) for y in range(W) if I[x][y]!=5 and x<sep}:
                pass
    # collect components above separator, excluding color 2
    comps=[]
    seen=set(); below=False
    for r in range(sep):
        for c in range(W):
            v=I[r][c]
            if v!=2 and (r,c) not in seen:
                st=[(r,c)]; cs={(r,c)}
                while st:
                    a,b=st.pop()
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dx,b+dy
                        if 0<=x<sep and 0<=y<W and I[x][y]==v and (x,y) not in cs:
                            cs.add((x,y)); st.append((x,y))
                seen|=cs
                comps.append((v,sorted(cs)))
    # slot: columns of 2-object (min col of color2 component)
    comp2=None
    for r in range(sep):
        for c in range(W):
            if I[r][c]==2:
                st=[(r,c)]; cs={(r,c)}
                while st:
                    a,b=st.pop()
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dx,b+dy
                        if 0<=x<sep and 0<=y<W and I[x][y]==2 and (x,y) not in cs:
                            cs.add((x,y)); st.append((x,y))
                seen2|=cs
                comp2=cs
    mc=min(c for _,c in comp2)
    comps.sort(key=lambda o:o[1][0][1])  # by leftmost col descending? test later
    # place: the piece whose shape matches 2-object shape goes at slot; others stack below
    out=[[0]*W for _ in range(9)]
    slot_rows=[r for r in range(min(r for r,_ in comp2), max(r for r,_ in comp2)+1)]
    for i,(v,cs) in enumerate(comps):
        h=max(r for r,_ in cs)-min(r for r,_ in cs)+1
        w=max(c for _,c in cs)-min(c for _,c in cs)+1
        top = min(slot_rows[0]-1 if False else 0, 9-h) if i==0 else None
        rr = top if i==0 else top+h*i
        for (r,c) in cs:
            rc = mc + (c-min(c for _,c in cs)) - (w-1)//2 if i==0 else mc-(w-1)//2
            rr = rr + (r-min(r for r,_ in cs))
            if 0<=rr<9 and 0<=rc<W: out[rr][rc]=v
    return out
