        infos.append({'col':col,'shape':shape,'h':h,'w':w,'center':(sum(y for y,_ in comp)/len(comp), sum(x for _,x in comp)/len(comp))})
    # search translations minimizing total L1 movement, requiring pairwise 8-adjacency and no overlap
