                a=infos[i]['shape']; b=infos[j]['shape']
                if shapes_overlap(a,b,infos[i]['h'],infos[i]['w'],infos[j]['h'],infos[j]['w'],pos[i],pos[j]): ok=False;break
                if not adj_exists(pos[i],a,pos[j],b): ok=False;break
            if not ok: break
        return ok,tot
    bounds=[(round(ci['center'][0])+2,-round(ci['center'][0])-2, round(ci['center'][1])+2,-round(ci['center'][1])-2) for ci in infos]
    # coarse grid search
